use vstd::prelude::*;

verus! {

pub spec const MAX: int = i32::MAX as int;
pub spec const MIN: int = i32::MIN as int;
spec fn insert_postcond (oline : Seq < char > , l : nat , nl : Seq < char > , p : nat , at_pos : nat , result : Seq < char >) -> bool { result . len () == l + p && (forall | i : int | 0 <= i < p ==> # [trigger] result [at_pos + i] == nl [i]) && (forall | i : int | 0 <= i < at_pos ==> # [trigger] result [i] == oline [i]) && (forall | i : int | 0 <= i < l - at_pos ==> # [trigger] result [at_pos + p + i] == oline [at_pos + i]) }
spec fn insert_precond (oline : Seq < char > , l : nat , nl : Seq < char > , p : nat , at_pos : nat) -> bool { l <= oline . len () && p <= nl . len () && at_pos <= l }
# [verifier :: loop_isolation (false)] fn insert (oline : & Vec < char > , l : usize , nl : & Vec < char > , p : usize , at_pos : usize) -> (result : Vec < char >) requires insert_precond (oline @ , l as nat , nl @ , p as nat , at_pos as nat) , l <= MAX - p , ensures insert_postcond (oline @ , l as nat , nl @ , p as nat , at_pos as nat , result @) , { let mut result = Vec :: with_capacity (l + p) ; let mut i = 0 ; while i < at_pos invariant i <= at_pos , result . len () == i , forall | j : int | 0 <= j < i ==> # [trigger] result @ [j] == oline @ [j] , decreases at_pos - i , { result . push (oline [i]) ; i += 1 ; } let mut j = 0 ; while j < p invariant j <= p , result . len () == at_pos + j , forall | k : int | 0 <= k < at_pos ==> # [trigger] result @ [k] == oline @ [k] , forall | k : int | 0 <= k < j ==> # [trigger] result @ [at_pos + k] == nl @ [k] , decreases p - j , { result . push (nl [j]) ; j += 1 ; } let mut k = 0 ; while k < l - at_pos invariant k <= l - at_pos , result . len () == at_pos + p + k , forall | m : int | 0 <= m < at_pos ==> # [trigger] result @ [m] == oline @ [m] , forall | m : int | 0 <= m < p ==> # [trigger] result @ [at_pos + m] == nl @ [m] , forall | m : int | 0 <= m < k ==> # [trigger] result @ [at_pos + p + m] == oline @ [at_pos + m] , decreases (l - at_pos) - k , { result . push (oline [at_pos + k]) ; k += 1 ; } result }

} // verus!